/**
 * Traverses a directory recursively and returns all file paths.
 */
function getFilesRecursively(dir: string, baseDir: string = dir): string[] {
  let results: string[] = [];
  if (!fs.existsSync(dir)) return results;
  const list = fs.readdirSync(dir);
  for (const file of list) {
    const filePath = path.join(dir, file);
    const stat = fs.statSync(filePath);

    // Ignore node_modules, .git, and output zip files
    if (file === 'node_modules' || file === '.git' || file.endsWith('.zip')) {
      continue;
    }

    if (stat.isDirectory()) {
      results = results.concat(getFilesRecursively(filePath, baseDir));
    } else {
      results.push(filePath);
    }
  }
  return results;
}

