/**
 * Importer: Decrypts, decompresses, and restores note files, sidecars, and configs.
 */
export async function importVault(
  archivePath: string,
  targetDir: string,
  pin: string
): Promise<void> {
  if (!fs.existsSync(archivePath)) {
    throw new Error(`Archive file not found at: ${archivePath}`);
  }

  const archiveBuffer = fs.readFileSync(archivePath);

  // Verify magic header
  const magic = archiveBuffer.subarray(0, 8).toString('utf8');
  if (magic !== 'ANYMDENC') {
    throw new Error('Invalid archive format or corrupted file header.');
  }

  const salt = archiveBuffer.subarray(8, 24);
  const iv = archiveBuffer.subarray(24, 40);
  const encryptedPayload = archiveBuffer.subarray(40);

  // Derive key using the same pbkdf2 settings
  const iterations = 10000;
  const key = crypto.pbkdf2Sync(pin, salt, iterations, 32, 'sha256');

  const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv);
  const decompressedPayload = Buffer.concat([
    decipher.update(encryptedPayload),
    decipher.final()
  ]);

  const rawJson = zlib.gunzipSync(decompressedPayload).toString('utf8');
  const vaultData: Record<string, { content: string; isBinary: boolean }> = JSON.parse(rawJson);

  for (const [relativePath, fileData] of Object.entries(vaultData)) {
    const destPath = path.join(targetDir, relativePath);
    fs.mkdirSync(path.dirname(destPath), { recursive: true });

    if (fileData.isBinary) {
      fs.writeFileSync(destPath, Buffer.from(fileData.content, 'base64'));
    } else {
      fs.writeFileSync(destPath, fileData.content, 'utf8');
    }
  }
}
